class Solution:
    def magicSigns(self, A: List[int]) -> List[int]:
        n = len(A); bit = [0] * (n + 1); res = []
        for i, v in enumerate(A):
            s, k = 0, v - 1                      # smaller values already seen (to the left)
            while k > 0:
                s += bit[k]; k -= k & -k
            sl = s; sr = v - 1 - sl
            ll = i - sl; lr = n - 1 - i - sr
            res.append(1 if sl * sr - ll * lr >= 0 else -1)
            k = v
            while k <= n:
                bit[k] += 1; k += k & -k
        return res

