class Solution {
public:
    vector<int> magicSigns(vector<int>& A) {
        int n = A.size(); vector<int> bit(n + 1, 0), res;
        for (int i = 0; i < n; i++) {
            int v = A[i]; long long sl = 0;
            for (int k = v - 1; k > 0; k -= k & -k) sl += bit[k];
            long long sr = v - 1 - sl, ll = i - sl, lr = n - 1 - i - sr;
            res.push_back(sl * sr - ll * lr >= 0 ? 1 : -1);
            for (int k = v; k <= n; k += k & -k) bit[k]++;
        }
        return res;
    }
};

